package br.com.marquesautodetail.api.favorito; import br.com.marquesautodetail.api.empresa.dto.EmpresaResponse; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/favoritos") public class FavoritoController{ private final FavoritoService service; public FavoritoController(FavoritoService service){this.service=service;} @PostMapping("/{empresaId}") public void favoritar(@PathVariable Long empresaId){service.favoritar(empresaId);} @GetMapping("/me") public List<EmpresaResponse> meus(){return service.listar();} @DeleteMapping("/{empresaId}") public void remover(@PathVariable Long empresaId){service.remover(empresaId);} }
